func brainLiveStateReport(ctx context.Context, runner CommandRunner, repoDir string, manifest *exportManifest) (brainLiveState, error) {
	var live brainLiveState
	if head, err := clibase.GitScalar(ctx, runner, repoDir, "rev-parse", "HEAD"); err == nil {
		live.Head = head
	} else {
		live.Warnings = append(live.Warnings, "HEAD unavailable: "+err.Error())
	}
	if branch, err := clibase.GitScalar(ctx, runner, repoDir, "branch", "--show-current"); err == nil {
		live.Branch = branch
	} else {
		live.Warnings = append(live.Warnings, "branch unavailable: "+err.Error())
	}
	status, err := gitStatusPorcelainAll(ctx, runner, repoDir)
	if err != nil {
		return live, err
	}
	// Apply the SAME ignore policy the semantic freshness check applies. This
	// was the one dirtiness computation in the brain that read raw `git status`,
	// and the gap showed up on the very first run in a pristine clone: the host
	// `entire` CLI that setup shells out to creates an empty
	// `.entire/logs/entire.log` inside the working tree, which every other
	// reader here already treats as ignored (brainIgnore skips the whole
	// `.entire` segment), but which made live.Dirty true, which graded the seed
	// axis "dirty-unindexed", which reported a clean onboarding as
	// "freshness: degraded". A successful setup must not end on a red line the
	// user did not cause.
	if ignore, ignoreErr := loadBrainIgnore(repoDir); ignoreErr != nil {
		live.Warnings = append(live.Warnings, "ignore rules unavailable: "+ignoreErr.Error())
	} else {
		status = filterWorktreeStatus(status, ignore)
	}
	live.Staged, live.Unstaged, live.Untracked = parseBrainLiveStatus(status)
	live.Dirty = len(live.Staged)+len(live.Unstaged)+len(live.Untracked) > 0
	// `git diff --shortstat HEAD` REFRESHES THE INDEX as a side effect, which
	// takes `.git/index.lock` and makes a concurrent human or agent git command
	// fail (issue #326). --no-optional-locks does not suppress that particular
	// refresh -- measured, see gitHardenConfig -- so the only fix is to stop
	// calling the porcelain. `diff-index` is the plumbing `git diff <commit>`
	// is built on and never refreshes.
	//
	// -M is load-bearing. `git diff` gets rename detection from diff.renames,
	// whose default is true; plumbing reads only the basic diff config and so
	// gets none. Without -M a rename is counted as a whole-file delete plus a
	// whole-file add, changing BOTH the file count and the insertion/deletion
	// counts (measured: " 3 files changed, 6 insertions(+), 5 deletions(-)"
	// against the porcelain's " 2 files changed, 1 insertion(+)" on the same
	// worktree). With -M the output is byte-identical to the porcelain on git
	// 2.54.0, including against a stat-dirty-but-identical file -- the
	// --shortstat path reads content, so such a file is dropped from both.
	// (The raw `diff-index --name-status` path does NOT read content and would
	// report it, which is why this swap is safe only for stat output.)
	if stat, err := clibase.GitScalar(ctx, runner, repoDir, "diff-index", "-M", "--shortstat", "HEAD"); err == nil {
		live.DiffStat = stat
	} else {
		live.Warnings = append(live.Warnings, "diff stat unavailable: "+err.Error())
	}
	if manifest != nil && manifest.Sources != nil && manifest.Sources.Semantic != nil {
		files, err := changedSemanticFiles(ctx, runner, repoDir)
		if err == nil {
			live.ChangedFiles = files
		} else {
			live.Warnings = append(live.Warnings, "changed file list unavailable: "+err.Error())
		}
	}
	return live, nil

